+.message-item {
+    position: relative;
+    padding: 8px 12px;
+    border-radius: 4px;
+    transition: background 0.1s;
+}
+
+.message-item:hover {
+    background: #2e3035;
+}
+
+.message-header {
+    display: flex;
+    align-items: baseline;
+    gap: 8px;
+    margin-bottom: 2px;
+}
+
+.message-author {
+    font-weight: 600;
+    color: #fff;
+    font-size: 0.9rem;
+}
+
+.message-time {
+    font-size: 0.72rem;
+    color: #949ba4;
+}
+
+.message-content {
+    font-size: 0.9rem;
+    line-height: 1.4;
+    word-break: break-word;
+}
+
+/* Reactions */
+.message-reactions {
+    display: flex;
+    gap: 4px;
+    margin-top: 6px;
+    flex-wrap: wrap;
+}
+
+.reaction-badge {
+    background: #2b2d31;
+    border: 1px solid #3f4147;
+    border-radius: 4px;
+    padding: 2px 8px;
+    font-size: 0.8rem;
+    cursor: pointer;
+    color: #dbdee1;
+    transition: background 0.15s;
+}
+
+.reaction-badge:hover {
+    background: #404249;
+}
+
+/* Thread link */
+.thread-link {
+    background: none;
+    border: none;
+    color: #00a8fc;
+    font-size: 0.8rem;
+    cursor: pointer;
+    padding: 4px 0;
+    margin-top: 4px;
+}
+
+.thread-link:hover {
+    text-decoration: underline;
+}
+
+/* Message actions (hover) */
+.message-actions {
+    position: absolute;
+    top: -10px;
+    right: 12px;
+    display: flex;
+    gap: 2px;
+    background: #2b2d31;
+    border: 1px solid #3f4147;
+    border-radius: 4px;
+    padding: 2px;
+}
+
+.action-btn {
+    background: none;
+    border: none;
+    color: #b5bac1;
+    font-size: 0.75rem;
+    padding: 4px 8px;
+    cursor: pointer;
+    border-radius: 3px;
+}
+
+.action-btn:hover {
+    background: #404249;
+    color: #fff;
+}
+
+/* Emoji picker */
+.emoji-picker {
+    position: absolute;
+    top: -10px;
+    right: 90px;
+    display: flex;
+    gap: 2px;
+    background: #2b2d31;
+    border: 1px solid #3f4147;
+    border-radius: 4px;
+    padding: 4px;
+    z-index: 10;
+}
+
+.emoji-btn {
+    background: none;
+    border: none;
+    font-size: 1.1rem;
+    cursor: pointer;
+    padding: 4px;
+    border-radius: 3px;
+}
+
+.emoji-btn:hover {
+    background: #404249;
+}
+
+/* Message input */
+.message-input {
+    display: flex;
+    gap: 8px;
+    padding: 12px 16px;
+    border-top: 1px solid #3f4147;
+}
+
+.message-input textarea {
+    flex: 1;
+    background: #383a40;
+    border: none;
+    border-radius: 8px;
+    padding: 10px 14px;
+    color: #dbdee1;
+    font-size: 0.9rem;
+    resize: none;
+    min-height: 40px;
+    max-height: 120px;
+    font-family: inherit;
+}
+
+.message-input textarea::placeholder {
+    color: #6d6f78;
+}
+
+.message-input textarea:focus {
+    outline: none;
+}
+
+.send-button {
+    background: #5865f2;
+    color: #fff;
+    border: none;
+    border-radius: 8px;
+    padding: 10px 20px;
+    font-weight: 600;
+    cursor: pointer;
+    font-size: 0.85rem;
+    align-self: flex-end;
+    transition: background 0.15s;
+}
+
+.send-button:hover:not(:disabled) {
+    background: #4752c4;
+}
+
+.send-button:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+/* Thread panel */
+.chat-thread {
+    width: 25%;
+    min-width: 280px;
+    background: #2b2d31;
+    border-left: 1px solid #1e1f22;
+    color: #dbdee1;
+    display: flex;
+    flex-direction: column;
+}
+
+.thread-panel {
+    display: flex;
+    flex-direction: column;
+    height: 100%;
+}
+
+.thread-header {
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    padding: 12px 16px;
+    border-bottom: 1px solid #3f4147;
+}
+
+.thread-header h3 {
+    margin: 0;
+    font-size: 1rem;
+    color: #fff;
+}
+
+.close-btn {
+    background: none;
+    border: none;
+    color: #b5bac1;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 4px 8px;
+    border-radius: 4px;
+}
+
+.close-btn:hover {
+    background: #404249;
+    color: #fff;
+}
+
+.thread-root-message {
+    padding: 12px 16px;
+    border-bottom: 1px solid #3f4147;
+    background: #232428;
+}
+
+.thread-root-message .message-author {
+    font-size: 0.85rem;
+}
+
+.thread-root-message .message-content {
+    margin-top: 4px;
+    font-size: 0.85rem;
+    color: #b5bac1;
+}
+
+.thread-messages {
+    flex: 1;
+    overflow-y: auto;
+    padding: 12px 16px;
+    display: flex;
+    flex-direction: column;
+    gap: 8px;
+}
+
+.thread-reply {
+    padding: 6px 0;
+}
+
+.thread-reply .message-content {
+    font-size: 0.85rem;
+}
+

